import { fileURLToPath } from 'node:url';

// Generated by scripts/font-subset.py from NotoSansCJKkr-Bold.otf.
// The full font remains the authoritative fallback for codepoints outside these
// deterministic ranges (including Japanese and supplementary-plane CJK).
export const bundledVArchiveFullFontPath = fileURLToPath(new URL('../assets/fonts/NotoSansCJKkr-Bold.otf', import.meta.url));
export const bundledVArchiveKoreanSubsetFontPath = fileURLToPath(new URL('../assets/fonts/NotoSansCJKkr-Bold-KR-Subset.otf', import.meta.url));
export const vArchiveKoreanSubsetCoverageRanges = Object.freeze([
  [0x20, 0x7e],
  [0xa0, 0xff],
  [0x1100, 0x11ff],
  [0x2192, 0x2192],
  [0x2605, 0x2605],
  [0x2713, 0x2713],
  [0x3131, 0x318e],
  [0xac00, 0xd7a3],
]);

export function selectVArchiveFont(textContent) {
  let unsupportedCodepointCount = 0;
  for (const character of String(textContent ?? '')) {
    const codepoint = character.codePointAt(0);
    if (!isVArchiveSubsetCodepointSupported(codepoint)) unsupportedCodepointCount += 1;
  }
  const useSubset = unsupportedCodepointCount === 0;
  return {
    kind: useSubset ? 'subset' : 'full',
    fontPath: useSubset ? bundledVArchiveKoreanSubsetFontPath : bundledVArchiveFullFontPath,
    unsupportedCodepointCount,
  };
}

export function isVArchiveSubsetCodepointSupported(codepoint) {
  return vArchiveKoreanSubsetCoverageRanges.some(([start, end]) => codepoint >= start && codepoint <= end);
}
